window.OBJ = [{"code":"M204.1","t":"La ricerca di mercato","g":"So analizzare l’importanza della ricerca di mercato per le aziende, identificando le informazioni necessarie per prendere decisioni e descrivendo i metodi utilizzati per raccogliere questi dati.","col":"teal","ic":"search","ch":[{"k":"qcm","q":"Qual è lo scopo principale di una ricerca di mercato?","a":["Raccogliere informazioni per decidere in modo consapevole","Fissare i salari di tutti i collaboratori per l’anno","Sostituire tutta la pubblicità con sondaggi online","Eliminare definitivamente la concorrenza sul mercato"],"ex":"Lo scopo principale è raccogliere informazioni per prendere decisioni consapevoli.","ref":"Lezione 4.1.2"},{"k":"multi","q":"Perché la ricerca di mercato è diventata necessaria?","good":["Concorrenza accresciuta","Mercati saturi","Globalizzazione","Rincaro delle materie prime"],"bad":["Calo del numero di prodotti","Scomparsa della concorrenza"],"ex":"Sono i quattro motivi del corso.","ref":"Lezione 4.1.1"},{"k":"tf","q":"Oggi un’azienda può basarsi solo sulla sua esperienza passata per conoscere il suo mercato.","v":false,"ex":"Il mercato è diventato più grande e complesso: l’esperienza non basta più, servono metodi di marketing.","ref":"Lezione 4.1"},{"k":"qcm","q":"Che cosa significa un «mercato saturo»?","a":["I clienti hanno già ciò che serve: bisogna innovare","Non c’è più alcun prodotto in vendita in questo settore","I prezzi vi sono fissati ogni anno dallo Stato","Il mercato è chiuso alle aziende straniere"],"ex":"In un mercato saturo, con beni sostitutivi, l’azienda deve innovare.","ref":"Lezione 4.1.1"},{"k":"multi","q":"Quali metodi di raccolta dei dati cita il corso?","good":["Osservazione di Internet","Lettura di articoli di stampa","Colloqui con clienti","Colloqui con fornitori"],"bad":["Lettura degli oroscopi","Sorteggio dei clienti"],"ex":"Osservazione (Internet, stampa) e colloqui con clienti e fornitori.","ref":"Lezione 4.1.3"},{"k":"case","s":"L’azienda EcoTextiles, che vende abiti in fibre naturali, vede calare le sue vendite.","q":"Quali metodi ha usato per capire perché?","a":["Sondaggi online e colloqui con clienti fedeli","Un calo di tutti i prezzi senza chiedere niente a nessuno","Un cambiamento completo di logo, nome e colori","Il licenziamento di una parte del personale di vendita"],"ex":"EcoTextiles ha condotto sondaggi online e colloqui con i suoi clienti fedeli.","ref":"Lezione 4.1.3"},{"k":"case","s":"La ricerca di EcoTextiles mostra due cause: pochi stili diversi e prezzi troppo alti rispetto alla concorrenza.","q":"Quale decisione è coerente con questi risultati?","a":["Diversificare le collezioni e rivedere i prezzi","Abbandonare le fibre naturali per la plastica","Aumentare ancora i prezzi per compensare il calo","Chiudere il negozio online e tenere un solo negozio"],"ex":"EcoTextiles ha diversificato le collezioni e rivisto i prezzi, mantenendo i suoi standard ecologici.","ref":"Lezione 4.1.3"},{"k":"multi","q":"Quali informazioni permette di identificare una ricerca di mercato?","good":["I concorrenti esistenti e potenziali","Gli opinion leader","Le nuove tendenze","I bisogni del mercato"],"bad":["Gli orari del personale","Il colore dei camion"],"ex":"Situazione attuale, persone influenti, tendenze e bisogni.","ref":"Lezione 4.1.2"},{"k":"match","q":"Abbini ogni obiettivo della ricerca al suo contenuto.","p":[["Situazione attuale","Concorrenti diretti e indiretti"],["Nuove tendenze","Evoluzione delle preferenze"],["Bisogni del mercato","Aspettative attuali e future"],["Riduzione dei rischi","Anticipare gli errori di decisione"]],"ex":"Sono gli obiettivi specifici della ricerca di mercato.","ref":"Lezione 4.1.2"},{"k":"qcm","q":"Chi sono le «persone influenti» su un mercato?","a":["Gli opinion leader e i grandi distributori","Gli apprendisti del primo anno dell’azienda","Gli autisti che consegnano le merci","I nuovi clienti che acquistano una sola volta"],"ex":"Il corso cita gli opinion leader e i grandi distributori.","ref":"Lezione 4.1.2"},{"k":"case","s":"Un’azienda di materiale da escursionismo vuole lanciare uno zaino per le bici elettriche.","q":"A quale domanda deve aiutare a rispondere anzitutto la ricerca di mercato?","a":["Questo prodotto risponde a un bisogno dei clienti?","Di che colore sarà il camion di consegna?","Quanti posteggi conta il deposito?","In che giorno si terrà la festa del personale?"],"ex":"Un’analisi precoce risponde a domande come: offriamo qualcosa di nuovo? Puntiamo a un nuovo gruppo?","ref":"Lezione 4.1.1"},{"k":"order","q":"Metta in ordine la procedura seguita da EcoTextiles.","a":["Constatare il calo delle vendite","Interrogare i clienti","Analizzare le cause","Decidere i cambiamenti","Adattare le collezioni e i prezzi"],"ex":"Dalla ricerca di mercato alla decisione, poi all’azione.","ref":"Lezione 4.1.3"},{"k":"tf","q":"Ogni cambiamento di mercato richiede una ricerca approfondita.","v":true,"ex":"Il corso lo precisa.","ref":"Lezione 4.1.1"},{"k":"qcm","q":"A che cosa servono le previsioni di mercato?","a":["A orientare le attività commerciali","A calcolare le ore supplementari","A fissare l’affitto del deposito","A sostituire l’inventario delle scorte"],"ex":"Le previsioni, basate sulla ricerca di mercato, orientano le attività commerciali.","ref":"Lezione 4.1.3"},{"k":"case","s":"Un concorrente apre un negozio online che vende gli stessi prodotti della sua azienda, il 10 % meno caro.","q":"Perché qui è utile una ricerca di mercato?","a":["Per analizzare la minaccia e reagire per tempo","Per copiare esattamente il suo sito Internet","Per aspettare che il concorrente scompaia","Per abbassare tutti i salari del 10 %"],"ex":"Analizzare opportunità e minacce e agire per tempo è cruciale.","ref":"Lezione 4.1.2"},{"k":"sort","q":"Concorrente diretto o indiretto di un’azienda di consegna di pasti?","c":["Diretto","Indiretto"],"it":[["Un’altra piattaforma di consegna di pasti",0],["Un supermercato che vende piatti pronti",1],["Un ristorante che consegna da sé",0],["Una mensa aziendale",1],["Un servizio di consegna concorrente",0],["Un negozio di prodotti surgelati",1]],"ex":"Diretto: stesso prodotto, stesso bisogno. Indiretto: altra soluzione allo stesso bisogno.","ref":"Lezione 4.1.2"},{"k":"odd","q":"Quale non è un obiettivo della ricerca di mercato?","a":["Aumentare il numero di pause","Identificare i concorrenti","Individuare le tendenze","Ridurre i rischi di decisione"],"ex":"Gli altri tre sono obiettivi citati dal corso.","ref":"Lezione 4.1.2"},{"k":"fill","q":"La ricerca di mercato aiuta a minimizzare i ___ di decisioni sbagliate.","a":["rischi","salari","scorte","termini"],"ex":"Permette una decisione informata e l’anticipazione dei rischi.","ref":"Lezione 4.1.2"},{"k":"case","s":"Un’azienda vuole raggiungere gli studenti, un gruppo di clienti che non ha mai servito.","q":"Che cosa deve fare prima di lanciarsi?","a":["Studiare questo gruppo: bisogni, abitudini, concorrenza","Lanciare subito una campagna nazionale","Copiare l’offerta di un concorrente senza riflettere","Ridurre i prezzi senza conoscere la domanda"],"ex":"Puntare a un nuovo gruppo di clienti fa parte delle domande dell’analisi precoce.","ref":"Lezione 4.1.1"},{"k":"tf","q":"La ricerca di mercato aiuta a identificare opportunità di crescita.","v":true,"ex":"In sintesi: capire la concorrenza, identificare le opportunità, ridurre i rischi.","ref":"Lezione 4.1.2"},{"k":"case","s":"Il prezzo del cotone è aumentato fortemente quest’anno.","q":"Per un’azienda tessile, quale motivo per studiare il mercato è interessato?","a":["Il rincaro delle materie prime","La saturazione del mercato del cotone","La scomparsa della concorrenza","Il calo dei salari nel settore"],"ex":"Il rincaro delle materie prime è uno dei motivi citati.","ref":"Lezione 4.1.1"},{"k":"case","s":"Il suo capo le chiede di annotare per un mese le osservazioni dei clienti durante le consegne.","q":"A che cosa possono servire queste informazioni?","a":["Ad alimentare la ricerca di mercato dell’azienda","A niente: per l’azienda conta solo la vendita","A sanzionare i clienti che si lamentano troppo","A sostituire il bollettino di consegna firmato"],"ex":"I colloqui con i clienti fanno parte dei metodi di raccolta.","ref":"Lezione 4.1.3"},{"k":"qcm","q":"Che cosa vuol dire «beni sostitutivi»?","a":["Prodotti che possono sostituirne altri","Prodotti ritirati definitivamente dalla vendita","Prodotti la cui vendita è riservata allo Stato","Prodotti fabbricati solo all’estero"],"ex":"In un mercato saturo i clienti possono passare a un prodotto sostitutivo: bisogna innovare.","ref":"Lezione 4.1.1"},{"k":"case","s":"Una piccola azienda non ha il budget per un grande sondaggio.","q":"Quale metodo poco costoso propone il corso?","a":["Osservare Internet e la stampa, parlare con clienti e fornitori","Ingaggiare una grande agenzia internazionale per un anno","Inviare un questionario cartaceo a tutte le economie domestiche della Svizzera","Rinunciare a ogni informazione e fidarsi dell’intuito"],"ex":"La ricerca di mercato può basarsi sull’osservazione e sui colloqui.","ref":"Lezione 4.1.3"},{"k":"qcm","q":"Perché bisogna agire per tempo dopo una ricerca di mercato?","a":["Le opportunità e le minacce evolvono in fretta","I risultati diventano segreti dopo un mese","La legge lo impone entro tre giorni","I clienti dimenticano le loro risposte"],"ex":"Il corso sottolinea che agire per tempo è cruciale.","ref":"Lezione 4.1.2"}]},{"code":"M204.2","t":"Il bisogno","g":"So spiegare il concetto di bisogno nella creazione di un mercato, descrivendo come influenza la domanda e dando esempi di bisogni specifici che hanno portato alla creazione di nuovi prodotti o servizi.","col":"indigo","ic":"bulb","ch":[{"k":"qcm","q":"Secondo il corso, che cos’è un bisogno?","a":["Il desiderio di colmare una mancanza","Il prezzo di vendita di un prodotto","Una scorta di merci al deposito","Un obbligo fissato dalla legge"],"ex":"Un bisogno è il desiderio di colmare una mancanza; soddisfarlo elimina la mancanza.","ref":"Lezione 4"},{"k":"tf","q":"Perché si crei un mercato ci vuole un bisogno.","v":true,"ex":"Il mercato nasce da un bisogno.","ref":"Lezione 4"},{"k":"multi","q":"Secondo che cosa variano i bisogni?","good":["L’età","Il Paese","La professione","Il luogo","L’epoca"],"bad":["Il colore degli occhi","Il giorno della settimana"],"ex":"Il corso cita l’età, il Paese, la professione, il luogo e l’epoca.","ref":"Lezione 4"},{"k":"case","s":"Un imprenditore constata che molte persone vogliono conservare foto e documenti a casa, senza dipendere da Internet.","q":"Quale prodotto ha potuto sviluppare a partire da questo bisogno?","a":["Dischi rigidi di archiviazione esterni (NAS)","Stampanti a getto d’inchiostro per l’ufficio","Chiavi d’auto elettroniche senza contatto","Abbonamenti di telefonia mobile illimitati"],"ex":"È l’esempio del corso: un bisogno identificato diventa un modello d’impresa.","ref":"Lezione 4"},{"k":"qcm","q":"Che cosa succede quando un bisogno è soddisfatto?","a":["La mancanza scompare","Il bisogno raddoppia","Il prezzo cala per forza","Il mercato chiude"],"ex":"La soddisfazione del bisogno elimina la mancanza.","ref":"Lezione 4"},{"k":"order","q":"Metta in ordine l’evoluzione degli scambi descritta dal corso.","a":["Raccogliere e conservare cereali selvatici","Specializzarsi (ceramica, attrezzi)","Scambiare il surplus con cibo","Negoziare il prezzo migliore","Incontrarsi nei mercati"],"ex":"Dal neolitico alla fine dell’età del bronzo, gli scambi hanno dato vita ai mercati.","ref":"Lezione 4"},{"k":"qcm","q":"Alla fine dell’età del bronzo, che cosa diventa cruciale nello scambio?","a":["La negoziazione per ottenere il prezzo migliore","L’imballaggio curato di ogni merce","La pubblicità diffusa dalla radio regionale","Il trasporto rapido delle merci in aereo"],"ex":"La negoziazione diventa cruciale per ottenere il prezzo migliore.","ref":"Lezione 4"},{"k":"case","s":"Con il telelavoro molte persone cercano sedie da ufficio comode per casa.","q":"Che cosa mostra questo esempio?","a":["Un nuovo bisogno crea una domanda per un prodotto","I bisogni non cambiano mai con l’epoca","Il telelavoro ha fatto scomparire il mercato","Solo gli uffici delle aziende acquistano sedie"],"ex":"I bisogni variano secondo l’epoca e il luogo; influenzano la domanda.","ref":"Lezione 4"},{"k":"sort","q":"Questo bisogno dipende soprattutto da…","c":["L’età","Il luogo","La professione"],"it":[["Un passeggino per un neonato",0],["Catene da neve in montagna",1],["Scarpe di sicurezza al deposito",2],["Un apparecchio acustico a 80 anni",0],["Un ombrellone in riva al lago",1],["Un software di gestione delle scorte",2]],"ex":"I bisogni variano secondo l’età, il luogo o la professione.","ref":"Lezione 4"},{"k":"tf","q":"I bisogni sono gli stessi per tutti, ovunque e in tutte le epoche.","v":false,"ex":"Variano secondo l’età, il Paese, la professione, il luogo e l’epoca.","ref":"Lezione 4"},{"k":"match","q":"Abbini ogni bisogno al prodotto o servizio che ha fatto nascere.","p":[["Conservare i propri file a casa","Disco rigido esterno (NAS)"],["Ricevere gli acquisti a domicilio","Consegna di pacchi"],["Pagare senza contanti","Pagamento con carta"],["Spostarsi senza auto","Bici in libero servizio"]],"ex":"Un bisogno identificato può diventare un modello d’impresa.","ref":"Lezione 4 · esempi (non nel materiale del corso, tranne il NAS)"},{"k":"case","s":"Gli acquisti online aumentano fortemente. I clienti vogliono ricevere i pacchi anche quando sono assenti.","q":"Quale servizio risponde a questo bisogno?","a":["Armadietti per pacchi accessibili 24 ore su 24","Negozi chiusi tutti i sabati","Cataloghi cartacei sempre più spessi ogni anno","Consegne organizzate solo la domenica"],"ex":"Un bisogno nuovo fa nascere un servizio nuovo.","ref":"Lezione 4 · esempio (non nel materiale del corso)"},{"k":"qcm","q":"Come influenza il bisogno la domanda?","a":["Più il bisogno è forte, più la domanda aumenta","Il bisogno non ha alcun effetto sulla domanda dei clienti","Un bisogno molto forte fa al contrario calare la domanda","La domanda dipende solo dal meteo del giorno"],"ex":"Senza bisogno, nessuna domanda; un bisogno forte fa salire la domanda.","ref":"Lezione 4"},{"k":"fill","q":"Un mercato nasce da un ___, il desiderio di colmare una mancanza.","a":["bisogno","stock","contratto","prezzo"],"ex":"È il punto di partenza di ogni mercato.","ref":"Lezione 4"},{"k":"case","s":"In un Paese caldo, un’azienda svizzera vuole vendere le sue stufette elettriche.","q":"Che cosa rischia?","a":["Di non trovare un bisogno, quindi poca domanda","Di vendere molto di più che sul mercato svizzero","Di creare subito un monopolio in quel Paese","Di dover abbassare i salari del suo personale"],"ex":"I bisogni variano secondo il Paese e il luogo.","ref":"Lezione 4"},{"k":"odd","q":"Quale non è un fattore che fa variare i bisogni secondo il corso?","a":["Il colore dei capelli","L’età","La professione","L’epoca"],"ex":"Il corso cita l’età, il Paese, la professione, il luogo e l’epoca.","ref":"Lezione 4"},{"k":"qcm","q":"Quali mercati esistono ancora oggi, secondo il corso?","a":["Mercati di verdura, di pesce e di Natale","Solo i grandi mercati borsistici mondiali","Solo i mercati online su Internet","Nessuno: i mercati sono tutti scomparsi da tempo"],"ex":"Il corso cita i mercati di verdura, di pesce e di Natale.","ref":"Lezione 4"},{"k":"case","s":"Un’azienda lancia scatole di pasti da cucinare, consegnate con gli ingredienti esatti, per le persone di fretta.","q":"Quale bisogno ha identificato?","a":["Cucinare in modo sano senza perdere tempo a fare la spesa","Mangiare ogni giorno al ristorante del quartiere","Acquistare più stoviglie per la cucina","Fare la spesa al supermercato ogni giorno"],"ex":"Identificare un bisogno preciso permette di creare un prodotto nuovo.","ref":"Lezione 4 · esempio (non nel materiale del corso)"},{"k":"tf","q":"Nel neolitico i prodotti non necessari venivano scambiati con cibo.","v":true,"ex":"Con la specializzazione (ceramica, attrezzi, taglio della pietra) il surplus si scambia con cibo.","ref":"Lezione 4"},{"k":"case","s":"Un impiegato in logistica nota che i suoi clienti chiedono spesso imballaggi riutilizzabili.","q":"Che cosa può fare la sua azienda di questa osservazione?","a":["Proporre un servizio di imballaggi con deposito","Ignorare questa richiesta dei clienti","Raddoppiare il prezzo dei cartoni monouso","Vietare gli imballaggi riutilizzabili"],"ex":"Individuare un bisogno è l’occasione per creare un’offerta.","ref":"Lezione 4 · esempio (non nel materiale del corso)"},{"k":"qcm","q":"Perché l’epoca fa variare i bisogni?","a":["Gli stili di vita e le tecniche cambiano","La gente dimentica i suoi vecchi bisogni","Il prezzo dell’oro cambia ogni anno","Le leggi vietano i vecchi bisogni"],"ex":"Un bisogno di oggi (ricaricare un telefono) non esisteva 50 anni fa.","ref":"Lezione 4"},{"k":"multi","q":"Quali sono esempi di bisogni che hanno creato nuovi servizi?","good":["Ricevere i pacchi in un punto di ritiro","Pagare con il telefono","Seguire il proprio pacco online"],"bad":["Aspettare un pacco senza informazioni","Pagare solo in contanti"],"ex":"Ognuno di questi servizi risponde a un bisogno recente.","ref":"Lezione 4 · esempi (non nel materiale del corso)"},{"k":"case","s":"Il numero di persone anziane aumenta in Svizzera.","q":"Quale mercato potrebbe svilupparsi?","a":["La consegna della spesa a domicilio per anziani","La vendita di passeggini sportivi per neonati","I giocattoli per bambini di tre anni","I manuali scolastici per apprendisti del 1° anno"],"ex":"I bisogni variano secondo l’età: una popolazione più anziana crea nuovi bisogni.","ref":"Lezione 4"},{"k":"qcm","q":"Che cosa trasforma un bisogno in mercato?","a":["L’incontro tra un’offerta e una domanda","Una decisione presa da solo dal governo","La chiusura dei negozi della concorrenza","Il calo dei salari in tutto il settore"],"ex":"Un mercato riunisce venditori e acquirenti attorno a un bisogno.","ref":"Lezione 4"},{"k":"case","s":"Durante un’ondata di caldo le vendite di ventilatori esplodono.","q":"Che cosa mostra questa situazione?","a":["Un bisogno improvviso fa salire la domanda","Il bisogno non ha alcun legame con il meteo","I ventilatori sono un monopolio","La domanda cala quando fa caldo"],"ex":"Il bisogno influenza direttamente la domanda.","ref":"Lezione 4"}]},{"code":"M204.3","t":"Le forme di mercato","g":"So confrontare i tipi di mercato (monopolio, oligopolio, polipolio) spiegandone le caratteristiche e valutandone l’impatto sulla concorrenza e sulle strategie delle aziende.","col":"violet","ic":"nodes","ch":[{"k":"match","q":"Abbini ogni forma di mercato alla sua definizione.","p":[["Monopolio","Un solo fornitore"],["Oligopolio","Pochi fornitori"],["Polipolio","Molti fornitori e molti acquirenti"],["Monopsonio","Un solo acquirente"]],"ex":"Le forme di mercato descrivono la struttura dell’offerta e della domanda.","ref":"Lezione 4.2.2"},{"k":"qcm","q":"Quale esempio dà il corso per un monopolio?","a":["Le condotte d’acqua","Il mercato settimanale","L’alloggio","Il petrolio"],"ex":"Gasdotti, condotte d’acqua, rete di trasporto.","ref":"Lezione 4.2.2"},{"k":"qcm","q":"Quale esempio dà il corso per un oligopolio?","a":["La rete mobile","Il mercato settimanale","Le condotte d’acqua","Un datore di lavoro unico"],"ex":"Petrolio, elettricità, rete mobile.","ref":"Lezione 4.2.2"},{"k":"qcm","q":"Quale esempio dà il corso per un polipolio?","a":["Il mercato settimanale","Il gasdotto regionale","La rete di telefonia mobile","L’elettricità del Paese"],"ex":"Mercato settimanale, alloggio.","ref":"Lezione 4.2.2"},{"k":"sort","q":"Classifichi ogni mercato secondo la sua forma.","c":["Monopolio","Oligopolio","Polipolio"],"it":[["Rete di condotte d’acqua",0],["Operatori di telefonia mobile",1],["Bancarelle del mercato del sabato",2],["Gasdotto regionale",0],["Compagnie petrolifere",1],["Affitto di appartamenti in città",2]],"ex":"Un solo fornitore, pochi fornitori o molti fornitori.","ref":"Lezione 4.2.2"},{"k":"tf","q":"In un polipolio la libera concorrenza influenza l’assortimento e i prezzi.","v":true,"ex":"Molti fornitori e molti acquirenti: la concorrenza agisce liberamente.","ref":"Lezione 4.2.2"},{"k":"qcm","q":"Che cos’è un monopsonio?","a":["Un solo acquirente di fronte a numerosi offerenti","Un solo fornitore di fronte a numerosi clienti","Due fornitori che si accordano sui prezzi","Un mercato senza alcun acquirente"],"ex":"Il monopsonio è raro: per esempio un datore di lavoro di fronte a diversi candidati.","ref":"Lezione 4.2.2"},{"k":"case","s":"In una valle isolata assume una sola grande fabbrica. Una cinquantina di persone cerca lavoro.","q":"Di quale forma di mercato del lavoro si tratta?","a":["Un monopsonio","Un polipolio","Un oligopolio","Un mercato aperto"],"ex":"Un solo richiedente di lavoro (il datore di lavoro) di fronte a numerosi offerenti.","ref":"Lezione 4.2.2"},{"k":"case","s":"In un mercato settimanale dieci bancarelle vendono mele. Un venditore aumenta fortemente il suo prezzo.","q":"Che cosa rischia?","a":["I clienti comprano alle altre bancarelle","I clienti devono pagare, non hanno scelta","Le altre bancarelle devono chiudere","Il prezzo delle mele aumenta ovunque"],"ex":"In un polipolio la concorrenza limita i prezzi.","ref":"Lezione 4.2.2"},{"k":"case","s":"Tre operatori si spartiscono la rete mobile svizzera. Uno abbassa i suoi prezzi.","q":"Quale reazione è probabile da parte degli altri due?","a":["Osservano e spesso adattano i loro prezzi","Non reagiscono mai a questo cambiamento","Lasciano subito il mercato svizzero","Diventano insieme un monopolio legale"],"ex":"In un oligopolio ogni fornitore sorveglia da vicino i pochi altri.","ref":"Lezione 4.2.2 · strategia (non nel materiale del corso)"},{"k":"qcm","q":"In quale forma di mercato la concorrenza è più forte?","a":["Il polipolio","Il monopolio","L’oligopolio","Il monopsonio"],"ex":"Molti fornitori: ognuno deve distinguersi per assortimento e prezzo.","ref":"Lezione 4.2.2"},{"k":"qcm","q":"In quale forma di mercato non c’è alcuna concorrenza tra fornitori?","a":["Il monopolio","Il polipolio","L’oligopolio","Il mercato settimanale"],"ex":"Un solo fornitore, senza concorrenza.","ref":"Lezione 4.2.2"},{"k":"order","q":"Ordini queste forme di mercato dal numero più piccolo al più grande di fornitori.","a":["Monopolio","Oligopolio","Polipolio"],"ex":"Uno solo, pochi, molti.","ref":"Lezione 4.2.2"},{"k":"case","s":"La sua azienda di trasporto è una delle centinaia di piccole ditte di traslochi del Paese.","q":"Quale strategia è adatta?","a":["Distinguersi per servizio, qualità o prezzo","Fissare liberamente prezzi molto alti","Aspettare che i clienti arrivino da soli","Accordarsi in segreto con tutti i concorrenti"],"ex":"In un polipolio bisogna distinguersi da numerosi concorrenti.","ref":"Lezione 4.2.2 · strategia (non nel materiale del corso)"},{"k":"odd","q":"Quale non è una forma di mercato del corso?","a":["Il multipolio","Il monopolio","L’oligopolio","Il polipolio"],"ex":"Il corso cita monopolio, oligopolio, polipolio e monopsonio.","ref":"Lezione 4.2.2"},{"k":"fill","q":"Un mercato con pochi fornitori e una domanda importante è un ___.","a":["oligopolio","monopolio","polipolio","monopsonio"],"ex":"Oligopolio: petrolio, elettricità, rete mobile.","ref":"Lezione 4.2.2"},{"k":"tf","q":"Il monopsonio è una forma di mercato frequente.","v":false,"ex":"Il corso lo descrive come raro.","ref":"Lezione 4.2.2"},{"k":"case","s":"Una compagnia gestisce da sola la rete di distribuzione dell’acqua di una città.","q":"Perché non ci sono più reti concorrenti?","a":["Costruire più reti idriche costerebbe troppo","La legge vieta di bere l’acqua di un fornitore concorrente","Gli abitanti della città rifiutano ogni forma di concorrenza","L’acqua potabile non può essere venduta ai privati"],"ex":"Per le reti (acqua, gas, ferrovia) una sola rete è spesso più razionale: è un monopolio.","ref":"Lezione 4.2.2 · Non nel materiale del corso · effetti di un monopolio"},{"k":"multi","q":"Quali esempi del corso sono oligopoli?","good":["Petrolio","Elettricità","Rete mobile"],"bad":["Mercato settimanale","Alloggio"],"ex":"Pochi grandi fornitori dominano questi mercati.","ref":"Lezione 4.2.2"},{"k":"case","s":"Una nuova piccola azienda vuole vendere petrolio greggio in Svizzera.","q":"Quale difficoltà incontrerà su questo mercato?","a":["Pochi grandi fornitori dominano già il mercato","Nessuna: ci sono migliaia di piccoli concorrenti","Il mercato svizzero del petrolio è un monopsonio","Non c’è più alcuna domanda di petrolio in Svizzera"],"ex":"Il petrolio è un oligopolio: entrare di fronte a pochi giganti è difficile.","ref":"Lezione 4.2.2"},{"k":"qcm","q":"Quale effetto ha il numero di fornitori sul cliente?","a":["Più fornitori ci sono, più il cliente ha scelta","Il numero di fornitori non ha alcun effetto","Meno fornitori ci sono, più i prezzi calano","Il cliente sceglie sempre il monopolio"],"ex":"La concorrenza allarga la scelta e pesa sui prezzi.","ref":"Lezione 4.2.2"},{"k":"case","s":"Cerca un appartamento in città. Decine di proprietari offrono alloggi.","q":"Di quale forma di mercato si tratta?","a":["Un polipolio","Un monopolio","Un oligopolio","Un monopsonio"],"ex":"L’alloggio è un esempio di polipolio nel corso.","ref":"Lezione 4.2.2"},{"k":"qcm","q":"Come determina la struttura dell’offerta e della domanda la forma di mercato?","a":["Con il numero di fornitori e di acquirenti","Con il colore e la forma dei prodotti venduti","Con la dimensione dei magazzini dei fornitori","Con l’età media dei clienti di quel mercato"],"ex":"Le forme di mercato descrivono questa struttura.","ref":"Lezione 4.2.2"},{"k":"case","s":"Due grandi catene di supermercati si spartiscono la maggior parte delle vendite alimentari di un Paese.","q":"Come definire questo mercato?","a":["Un oligopolio","Un polipolio perfetto","Un monopsonio","Un mercato chiuso"],"ex":"Pochi grandi fornitori dominano: è un oligopolio.","ref":"Lezione 4.2.2"},{"k":"tf","q":"In un monopolio l’azienda non ha bisogno di lottare contro concorrenti per tenersi i clienti.","v":true,"ex":"Senza concorrenza la pressione per abbassare i prezzi o innovare è debole.","ref":"Lezione 4.2.2 · Non nel materiale del corso · effetti di un monopolio"}]},{"code":"M204.4","t":"Classificare i mercati","g":"So descrivere i criteri di classificazione dei mercati, come gli oggetti scambiati, le funzioni e l’accesso, dando esempi concreti per ogni categoria.","col":"coral","ic":"tags","ch":[{"k":"multi","q":"Secondo quali criteri il corso classifica i mercati?","good":["L’oggetto o il servizio scambiato","La funzione","Il tipo di accesso"],"bad":["Il colore del logo","Il numero di dipendenti"],"ex":"Oggetto o servizio, funzione (approvvigionamento o vendita) e accesso (aperto, chiuso, limitato).","ref":"Lezione 4.2.1"},{"k":"match","q":"Abbini ogni mercato a un esempio.","p":[["Beni di consumo","Abbigliamento e alimentazione"],["Lavoro","Offerta e domanda di impieghi"],["Monetario","Crediti a breve termine delle banche"],["Immobiliare","Terreni ed edifici"]],"ex":"Sono i tipi di mercato secondo l’oggetto scambiato.","ref":"Lezione 4.2.1"},{"k":"sort","q":"Classifichi ogni scambio secondo il tipo di mercato.","c":["Beni di consumo","Servizi","Immobiliare"],"it":[["Acquistare un libro",0],["Consultare un avvocato",1],["Acquistare un terreno",2],["Acquistare un computer",0],["Ricevere cure",1],["Affittare un magazzino",2]],"ex":"Oggetto materiale, prestazione o bene immobile.","ref":"Lezione 4.2.1"},{"k":"qcm","q":"Quali sono i due mercati secondo la funzione?","a":["Il mercato d’approvvigionamento e il mercato di vendita","Il mercato locale e il mercato globale dello stesso prodotto","Il mercato aperto e il mercato chiuso dallo Stato","Il monopolio e il polipolio di uno stesso settore"],"ex":"L’azienda acquista sul mercato d’approvvigionamento e vende sul mercato di vendita.","ref":"Lezione 4.2.1"},{"k":"case","s":"La sua azienda acquista cartoni e film estensibile da un fornitore, poi vende colli preparati a dei negozi.","q":"Su quale mercato acquista i cartoni?","a":["Il mercato d’approvvigionamento","Il mercato della vendita","Il mercato monetario delle banche","Il mercato del lavoro"],"ex":"Acquistare ciò di cui si ha bisogno: è il mercato d’approvvigionamento.","ref":"Lezione 4.2.1"},{"k":"match","q":"Abbini ogni tipo di accesso a un esempio del corso.","p":[["Aperto","Casse malati"],["Chiuso","Posta e FFS"],["Limitato","Taxi con concessione"]],"ex":"L’accesso può essere libero, chiuso da regole o limitato da condizioni.","ref":"Lezione 4.2.1"},{"k":"qcm","q":"Che cos’è un mercato aperto?","a":["Un mercato accessibile senza restrizioni","Un mercato aperto solo il sabato","Un mercato riservato allo Stato","Un mercato senza alcun cliente"],"ex":"Esempio del corso: le casse malati.","ref":"Lezione 4.2.1"},{"k":"qcm","q":"Che cos’è un mercato chiuso?","a":["Un mercato con accesso limitato da regole","Un mercato che è fallito l’anno scorso","Un mercato che vende solo di notte","Un mercato in cui non c’è alcun fornitore"],"ex":"Regole economiche o giuridiche limitano l’accesso: per esempio alcuni servizi pubblici.","ref":"Lezione 4.2.1"},{"k":"case","s":"Una città limita il numero di taxi concedendo concessioni, per evitare la saturazione.","q":"Che tipo di accesso al mercato è?","a":["Un mercato limitato","Un mercato aperto","Un mercato d’approvvigionamento","Un mercato monetario"],"ex":"È l’esempio del corso per un mercato limitato.","ref":"Lezione 4.2.1"},{"k":"tf","q":"Il mercato del lavoro riguarda l’offerta e la domanda di forza lavoro.","v":true,"ex":"È uno dei tipi di mercato secondo l’oggetto.","ref":"Lezione 4.2.1"},{"k":"qcm","q":"Su quale mercato una banca concede crediti a breve termine?","a":["Il mercato monetario","Il mercato immobiliare","Il mercato del lavoro","Il mercato di vendita"],"ex":"Il mercato monetario riguarda i crediti a breve termine delle banche.","ref":"Lezione 4.2.1"},{"k":"case","s":"Cerca un posto di impiegato/a in logistica dopo il suo AFC. Diverse aziende pubblicano offerte d’impiego.","q":"Su quale mercato si trova?","a":["Il mercato del lavoro","Il mercato dei servizi","Il mercato monetario","Il mercato immobiliare"],"ex":"Lei offre la sua forza lavoro; le aziende la richiedono.","ref":"Lezione 4.2.1"},{"k":"odd","q":"Quale non è un tipo di mercato secondo l’oggetto?","a":["Il mercato limitato","Il mercato immobiliare","Il mercato del lavoro","Il mercato monetario"],"ex":"«Limitato» è un tipo di accesso, non un oggetto scambiato.","ref":"Lezione 4.2.1"},{"k":"fill","q":"Le materie prime e l’arte fanno parte degli ___ mercati.","a":["altri","chiusi","monetari","immobiliari"],"ex":"Il corso li classifica in «altri».","ref":"Lezione 4.2.1"},{"k":"case","s":"Una galleria vende quadri durante un’asta.","q":"In quale categoria del corso si classifica questo mercato?","a":["Altri mercati (arte)","Beni di consumo","Mercato del lavoro","Mercato monetario"],"ex":"L’arte figura tra gli «altri mercati».","ref":"Lezione 4.2.1"},{"k":"order","q":"Per un’azienda di biciclette, metta in ordine il passaggio da un mercato all’altro.","a":["Acquistare telai e ruote (approvvigionamento)","Assemblare le biciclette","Stoccare le biciclette finite","Vendere ai negozi (vendita)"],"ex":"L’azienda acquista sul mercato d’approvvigionamento e vende sul mercato di vendita.","ref":"Lezione 4.2.1"},{"k":"case","s":"Un’azienda logistica affitta un nuovo magazzino di 5000 m².","q":"Su quale mercato agisce?","a":["Il mercato immobiliare","Il mercato dei beni di consumo","Il mercato monetario","Il mercato di vendita"],"ex":"Terreni ed edifici rientrano nel mercato immobiliare.","ref":"Lezione 4.2.1"},{"k":"multi","q":"Quali esempi sono servizi secondo il corso?","good":["Consulenza giuridica","Cure","Intrattenimento"],"bad":["Terreni","Libri"],"ex":"I servizi sono prestazioni, non oggetti.","ref":"Lezione 4.2.1"},{"k":"tf","q":"Una stessa azienda può agire contemporaneamente su un mercato d’approvvigionamento e su un mercato di vendita.","v":true,"ex":"Acquista da una parte e vende dall’altra.","ref":"Lezione 4.2.1"},{"k":"case","s":"Un privato vuole aprire un ufficio postale privato per distribuire lettere di 20 g.","q":"Che cosa constaterà?","a":["È un mercato chiuso: l’accesso è riservato","È un mercato aperto: può cominciare domani","È un mercato d’approvvigionamento","È un mercato monetario"],"ex":"Alcuni servizi pubblici, come quelli della Posta, sono mercati chiusi.","ref":"Lezione 4.2.1 · Non nel materiale del corso · Posta CH, monopolio residuo"},{"k":"qcm","q":"Perché limitare il numero di taxi con delle concessioni?","a":["Per evitare la saturazione del mercato","Per aumentare il numero di taxi","Per eliminare ogni concorrenza","Per abbassare il prezzo della benzina"],"ex":"Il corso lo precisa: evitare la saturazione.","ref":"Lezione 4.2.1"},{"k":"case","s":"Un assicurato cambia cassa malati ogni anno per pagare meno.","q":"Che cosa mostra questo esempio sul tipo di accesso?","a":["Il mercato è aperto: può scegliere liberamente","Il mercato è chiuso: non può cambiare","Il mercato è limitato da concessioni","Il mercato è un monopolio di Stato"],"ex":"Le casse malati sono l’esempio di mercato aperto del corso.","ref":"Lezione 4.2.1"},{"k":"qcm","q":"In quale mercato classifica l’acquisto di un telefono cellulare?","a":["Beni di consumo","Servizi alle persone","Mercato immobiliare","Mercato monetario"],"ex":"L’elettronica fa parte dei beni di consumo.","ref":"Lezione 4.2.1"},{"k":"case","s":"La sua azienda negozia con una banca un credito di tre mesi per finanziare una scorta di Natale.","q":"Su quale mercato negozia?","a":["Il mercato monetario","Il mercato del lavoro","Il mercato immobiliare","Il mercato di vendita"],"ex":"Crediti a breve termine delle banche: mercato monetario.","ref":"Lezione 4.2.1"},{"k":"case","s":"Un deposito assume cinque apprendisti impiegati in logistica per l’inizio dell’anno scolastico.","q":"Su quale mercato l’azienda agisce come richiedente?","a":["Il mercato del lavoro","Il mercato dei servizi","Il mercato immobiliare","Il mercato monetario"],"ex":"L’azienda richiede forza lavoro.","ref":"Lezione 4.2.1"}]},{"code":"M204.5","t":"La dimensione del mercato","g":"So spiegare le sfide logistiche legate alla dimensione di un mercato, confrontando le specificità dei mercati locali, regionali, nazionali e globali.","col":"amber","ic":"globe","ch":[{"k":"order","q":"Ordini i mercati dal più piccolo al più grande.","a":["Locale","Regionale","Nazionale","Internazionale","Globale"],"ex":"Sono i cinque gruppi della dimensione geografica.","ref":"Lezione 4.3.1"},{"k":"match","q":"Abbini ogni dimensione di mercato all’esempio del corso.","p":[["Locale","Negozio del villaggio"],["Regionale","Mercato settimanale"],["Nazionale","Telefonia mobile svizzera"],["Globale","Mercato finanziario"]],"ex":"Sono gli esempi della lezione 4.3.1.","ref":"Lezione 4.3.1"},{"k":"qcm","q":"Quale esempio dà il corso per un mercato internazionale?","a":["Il mercato dell’Unione europea","Il negozio del villaggio","Il mercato settimanale regionale","Il mercato finanziario mondiale"],"ex":"Internazionale: l’UE. Globale: il mercato finanziario.","ref":"Lezione 4.3.1"},{"k":"multi","q":"Da che cosa è determinata la dimensione di un mercato?","good":["La sua estensione geografica","Il numero di clienti potenziali"],"bad":["La dimensione del logo","Il numero di camion"],"ex":"Estensione geografica o numero di clienti potenziali.","ref":"Lezione 4.3"},{"k":"case","s":"Una panetteria di villaggio consegna ai suoi clienti in bicicletta entro un raggio di 3 km.","q":"Qual è il vantaggio logistico di questo mercato locale?","a":["Tragitti brevi e un contatto diretto con i clienti","Spedizioni regolari in container marittimo verso l’Asia","Formalità doganali complesse a ogni consegna","Termini di consegna di diverse settimane"],"ex":"Mercato locale: distanze brevi, relazioni dirette.","ref":"Non nel materiale del corso · sfide logistiche secondo la dimensione del mercato"},{"k":"case","s":"Un’azienda svizzera comincia a vendere i suoi prodotti in Giappone.","q":"Quale nuova sfida logistica compare?","a":["Dogana, trasporto lungo e normative diverse","Nessuna: è come consegnare nella città accanto al deposito","Solo un cambiamento di colore dell’imballaggio","Basta consegnare in bicicletta un po’ più lontano di prima"],"ex":"Su un mercato globale bisogna gestire dogana, lunghe distanze e regole diverse.","ref":"Non nel materiale del corso · sfide logistiche secondo la dimensione del mercato"},{"k":"qcm","q":"Perché la dimensione del mercato influenza il marketing?","a":["La strategia deve adattarsi al numero e al luogo dei clienti","La dimensione del mercato non ha alcun effetto sul marketing","Solo i mercati piccolissimi hanno bisogno di marketing","Il marketing è esattamente lo stesso in tutti i Paesi"],"ex":"La classificazione aiuta ad adattare la strategia.","ref":"Lezione 4.3"},{"k":"case","s":"Un negozio di biciclette di quartiere vuole attirare più clienti.","q":"Quale strategia è adatta al suo mercato locale?","a":["Campagne mirate e relazioni dirette","Una pubblicità televisiva diffusa in tutto il mondo","Un sito Internet tradotto in venti lingue straniere","Magazzini distribuiti su tre continenti"],"ex":"Un’azienda locale punta su campagne mirate e relazioni dirette.","ref":"Lezione 4.3.1"},{"k":"multi","q":"Quali fattori deve considerare un’azienda globale?","good":["Fattori culturali","Fattori economici","Fattori normativi"],"bad":["Solo il meteo locale","Solo il parere del vicino"],"ex":"Il corso cita fattori culturali, economici e normativi diversificati.","ref":"Lezione 4.3.1"},{"k":"sort","q":"Classifichi ogni azienda secondo la dimensione del suo mercato.","c":["Locale","Nazionale","Globale"],"it":[["Un negozio di alimentari di quartiere",0],["Un operatore di telefonia svizzero",1],["Una banca attiva sulle borse mondiali",2],["Un parrucchiere di villaggio",0],["Una catena di negozi presente in tutta la Svizzera",1],["Un fabbricante di orologi venduto in 80 Paesi",2]],"ex":"Dal villaggio al mondo intero.","ref":"Lezione 4.3.1"},{"k":"tf","q":"Servire un mercato nazionale richiede spesso una rete di centri di distribuzione regionali.","v":true,"ex":"Più il mercato è grande, più la rete logistica dev’essere organizzata.","ref":"Non nel materiale del corso · sfide logistiche secondo la dimensione del mercato"},{"k":"case","s":"Una PMI vodese vende ormai in tutta la Svizzera. I suoi clienti sono a Ginevra, Basilea, Lugano e Coira.","q":"Quale sfida logistica deve gestire?","a":["Organizzare i giri e i termini in diverse regioni","Far passare ogni pacco dalla dogana svizzera","Tradurre tutti i suoi prodotti in giapponese e cinese","Consegnare a piedi a tutti i clienti partendo da Losanna"],"ex":"Un mercato nazionale richiede una pianificazione dei trasporti su scala nazionale.","ref":"Non nel materiale del corso · sfide logistiche secondo la dimensione del mercato"},{"k":"odd","q":"Quale non è una sfida tipica di un mercato globale?","a":["Consegnare a un vicino in bicicletta","Gestire la dogana","Rispettare regole straniere","Gestire termini di trasporto lunghi"],"ex":"La consegna in bicicletta riguarda un mercato locale.","ref":"Non nel materiale del corso · sfide logistiche secondo la dimensione del mercato"},{"k":"fill","q":"Il mercato finanziario è un esempio di mercato ___.","a":["globale","locale","regionale","chiuso"],"ex":"È l’esempio del corso.","ref":"Lezione 4.3.1"},{"k":"qcm","q":"Quale modo di trasporto è tipico di un mercato globale?","a":["Il container marittimo o l’aereo","La cargo bike del quartiere","Il carrello a mano del negozio","La consegna a piedi da parte di un corriere locale"],"ex":"Le lunghe distanze richiedono trasporti internazionali.","ref":"Non nel materiale del corso · sfide logistiche secondo la dimensione del mercato"},{"k":"case","s":"La sua azienda consegna in Germania e in Francia, nell’Unione europea.","q":"Quale documento o procedura diventa importante alla frontiera?","a":["I documenti doganali","La licenza di pesca","Il libretto di famiglia","La carta fedeltà del cliente"],"ex":"La Svizzera non è membro dell’UE: le spedizioni passano dalla dogana.","ref":"Non nel materiale del corso · sfide logistiche secondo la dimensione del mercato"},{"k":"tf","q":"Più un mercato è grande, più la catena logistica è in genere lunga e complessa.","v":true,"ex":"Distanze, intermediari, regole e termini aumentano.","ref":"Non nel materiale del corso · sfide logistiche secondo la dimensione del mercato"},{"k":"case","s":"Un produttore di formaggio vende al mercato settimanale della sua regione.","q":"Qual è la dimensione del suo mercato?","a":["Regionale","Globale","Internazionale","Nazionale"],"ex":"Il mercato settimanale è l’esempio di mercato regionale del corso.","ref":"Lezione 4.3.1"},{"k":"qcm","q":"Quale vantaggio offre un grande mercato a un’azienda?","a":["Più clienti potenziali","Meno concorrenti ovunque","Nessun trasporto da organizzare","Regole identiche in tutti i Paesi"],"ex":"Più clienti potenziali, ma anche più complessità.","ref":"Lezione 4.3 · Non nel materiale del corso · sfide logistiche secondo la dimensione del mercato"},{"k":"case","s":"Una marca di cioccolato svizzera lancia una campagna in diversi Paesi dell’Asia.","q":"Perché non può copiare tale e quale la sua pubblicità svizzera?","a":["Le culture e le regole differiscono secondo i Paesi","La pubblicità è vietata in Asia","Il cioccolato si vende solo in Svizzera","I clienti asiatici non guardano la pubblicità"],"ex":"Un’azienda globale deve tener conto dei fattori culturali e normativi.","ref":"Lezione 4.3.1"},{"k":"multi","q":"Quali sfide logistiche aumentano con la dimensione del mercato?","good":["Distanze di trasporto","Termini di consegna","Formalità amministrative","Costi di trasporto"],"bad":["Contatto personale con ogni cliente","Numero di tragitti in bicicletta"],"ex":"Più il mercato è grande, più queste sfide aumentano.","ref":"Non nel materiale del corso · sfide logistiche secondo la dimensione del mercato"},{"k":"case","s":"Il suo magazzino serve solo i negozi di un cantone.","q":"Qual è la dimensione di questo mercato?","a":["Regionale","Globale","Internazionale","Monetario"],"ex":"Un cantone corrisponde a una regione.","ref":"Lezione 4.3.1"},{"k":"qcm","q":"Come si chiama nel corso il mercato svizzero della telefonia mobile?","a":["Un mercato nazionale","Un mercato locale","Un mercato globale","Un mercato chiuso"],"ex":"È l’esempio di mercato nazionale.","ref":"Lezione 4.3.1"},{"k":"case","s":"Un negozio online svizzero riceve ordini dal Canada.","q":"Che cosa deve prevedere per servire questi clienti?","a":["Un trasportatore internazionale e i documenti doganali","Un fattorino in bicicletta del quartiere per fare più in fretta","Un semplice francobollo svizzero da lettera incollato sul pacco","Niente di più che per una consegna in Svizzera"],"ex":"Vendere oltre le frontiere richiede una logistica internazionale.","ref":"Non nel materiale del corso · sfide logistiche secondo la dimensione del mercato"},{"k":"tf","q":"Un’azienda locale deve tener conto di numerosi fattori culturali e normativi stranieri.","v":false,"ex":"È soprattutto il caso delle aziende globali.","ref":"Lezione 4.3.1"}]},{"code":"M204.6","t":"I mercati chiusi","g":"So descrivere i meccanismi di accesso ai mercati chiusi, spiegando le restrizioni come licenze, concessioni ed esigenze di capitale minimo.","col":"emerald","ic":"lock","ch":[{"k":"qcm","q":"Che cosa limita l’accesso a un mercato chiuso?","a":["Regole economiche o giuridiche","Il colore dei prodotti offerti","Il numero di clienti soddisfatti","Il meteo della regione interessata"],"ex":"Il corso definisce il mercato chiuso come un accesso limitato da regole economiche o giuridiche.","ref":"Lezione 4.2.1"},{"k":"multi","q":"Quali restrizioni possono limitare l’accesso a un mercato?","good":["Una licenza","Una concessione","Un capitale minimo"],"bad":["Un logo colorato","Una carta fedeltà"],"ex":"Sono i tre meccanismi citati dall’obiettivo.","ref":"Non nel materiale del corso · accesso ai mercati chiusi"},{"k":"qcm","q":"Che cos’è una concessione?","a":["Un diritto concesso dall’autorità di esercitare un’attività","Uno sconto concesso a un cliente fedele ogni anno","Un contratto segreto tra due concorrenti","Una tassa riscossa su tutte le importazioni"],"ex":"Esempio del corso: i taxi con concessione.","ref":"Lezione 4.2.1 · Non nel materiale del corso · accesso ai mercati chiusi"},{"k":"qcm","q":"Che cos’è una licenza?","a":["Un’autorizzazione necessaria per esercitare o vendere","Una fattura inviata da un fornitore","Un bollettino di consegna firmato dal cliente","Uno sconto concesso su una grande quantità"],"ex":"Senza licenza non si può entrare in alcuni mercati (per esempio la vendita di alcol in alcuni cantoni).","ref":"Non nel materiale del corso · accesso ai mercati chiusi"},{"k":"num","q":"Qual è il capitale azionario minimo per fondare una SA in Svizzera (in franchi)?","n":100000,"tol":0,"u":"CHF","ex":"100 000 franchi, di cui almeno 50 000 franchi liberati alla fondazione (art. 621 CO).","ref":"Non nel materiale del corso · Codice delle obbligazioni, art. 621 e 773"},{"k":"num","q":"Qual è il capitale sociale minimo per fondare una Sagl in Svizzera (in franchi)?","n":20000,"tol":0,"u":"CHF","ex":"20 000 franchi, interamente liberati (art. 773 CO).","ref":"Non nel materiale del corso · Codice delle obbligazioni, art. 621 e 773"},{"k":"case","s":"Due amici vogliono fondare una SA di trasporto, ma hanno solo 30 000 franchi.","q":"Quale ostacolo incontrano?","a":["Il capitale minimo di una SA è di 100 000 franchi","Una SA deve contare almeno cinquanta dipendenti","Una SA non ha il diritto di fare trasporti","Serve loro l’accordo scritto di tutti i loro concorrenti"],"ex":"Il capitale minimo è una barriera d’accesso. Con 20 000 franchi sarebbe possibile una Sagl.","ref":"Non nel materiale del corso · Codice delle obbligazioni, art. 621 e 773"},{"k":"case","s":"Un’azienda vuole distribuire lettere di meno di 50 grammi in tutta la Svizzera.","q":"Perché non può farlo?","a":["La Posta ha un monopolio su queste lettere","Questo mercato è aperto a tutti senza condizioni","Basta comprare una concessione di taxi","La legge vieta di inviare lettere"],"ex":"La Confederazione concede alla Posta un monopolio sulle lettere fino a 50 g.","ref":"Non nel materiale del corso · Posta CH, monopolio residuo"},{"k":"tf","q":"La Posta Svizzera ha un monopolio sulle lettere fino a 50 grammi.","v":true,"ex":"È il «monopolio residuo» della Posta.","ref":"Non nel materiale del corso · Posta CH, monopolio residuo"},{"k":"tf","q":"I pacchi fino a 20 kg fanno parte del monopolio della Posta.","v":false,"ex":"I pacchi sono aperti alla concorrenza; il monopolio riguarda solo le lettere fino a 50 g.","ref":"Non nel materiale del corso · Posta CH, monopolio residuo"},{"k":"sort","q":"Mercato aperto o mercato chiuso (o limitato)?","c":["Aperto","Chiuso o limitato"],"it":[["Vendere t-shirt online",0],["Gestire un taxi con concessione",1],["Distribuire lettere di 20 g",1],["Aprire un negozio di biciclette",0],["Cambiare cassa malati",0],["Gestire una linea ferroviaria",1]],"ex":"Concessioni, monopoli e autorizzazioni chiudono o limitano l’accesso.","ref":"Lezione 4.2.1 · Non nel materiale del corso · accesso ai mercati chiusi"},{"k":"qcm","q":"Perché lo Stato può chiudere o limitare un mercato?","a":["Per garantire un servizio pubblico o evitare la saturazione","Per aumentare il prezzo di tutti i prodotti venduti","Per eliminare tutti i posti di lavoro di questo settore","Per favorire un’azienda amica del governo"],"ex":"Esempi del corso: servizi pubblici (Posta, FFS) e taxi (evitare la saturazione).","ref":"Lezione 4.2.1"},{"k":"match","q":"Abbini ogni restrizione a un esempio.","p":[["Concessione","Licenza di taxi della città"],["Monopolio legale","Lettere fino a 50 g"],["Capitale minimo","100 000 franchi per una SA"]],"ex":"Ogni meccanismo chiude o limita l’accesso a modo suo.","ref":"Non nel materiale del corso · accesso ai mercati chiusi"},{"k":"case","s":"Un autista vuole gestire un taxi in città, ma tutte le concessioni sono già assegnate.","q":"Quale soluzione ha?","a":["Aspettare una concessione libera o lavorare per un titolare","Circolare senza concessione proponendo prezzi più bassi","Creare una SA per poter aggirare la regola della città","Chiedere semplicemente l’accordo dei suoi primi clienti"],"ex":"In un mercato limitato, senza concessione, non si può esercitare come indipendente.","ref":"Lezione 4.2.1 · Non nel materiale del corso · accesso ai mercati chiusi"},{"k":"odd","q":"Quale non è un meccanismo di accesso ai mercati chiusi?","a":["Uno sconto fedeltà","Una licenza","Una concessione","Un capitale minimo"],"ex":"Lo sconto è uno strumento di vendita, non una barriera d’accesso.","ref":"Non nel materiale del corso · accesso ai mercati chiusi"},{"k":"fill","q":"Un taxi può circolare in alcune città solo con una ___.","a":["concessione","fattura","paletta","quietanza"],"ex":"È l’esempio del mercato limitato.","ref":"Lezione 4.2.1"},{"k":"qcm","q":"Quali esempi di mercati chiusi cita il corso?","a":["Servizi pubblici come la Posta e le FFS","I mercatini di Natale delle grandi città","Le casse malati del Paese","I negozi di abbigliamento del centro"],"ex":"Servizi pubblici in Svizzera: la Posta, le FFS.","ref":"Lezione 4.2.1"},{"k":"case","s":"Una start-up vuole far circolare i propri treni passeggeri sulla rete svizzera.","q":"Che cosa deve ottenere?","a":["Una concessione e l’accesso alla rete","Solo un sito Internet","Un semplice biglietto da visita","L’accordo dei suoi primi clienti"],"ex":"Il trasporto ferroviario è un mercato chiuso, soggetto a concessione.","ref":"Lezione 4.2.1 · Non nel materiale del corso · accesso ai mercati chiusi"},{"k":"qcm","q":"Qual è l’effetto di un capitale minimo elevato?","a":["Rende più difficile l’entrata sul mercato","Elimina ogni concorrenza sul mercato","Fa calare i prezzi per i clienti","Obbliga lo Stato ad aiutare finanziariamente l’azienda"],"ex":"Un capitale minimo è una barriera finanziaria all’entrata.","ref":"Non nel materiale del corso · accesso ai mercati chiusi"},{"k":"order","q":"Metta in ordine le procedure per entrare in un mercato soggetto a concessione.","a":["Informarsi sulle condizioni","Preparare l’incarto","Presentare la domanda all’autorità","Ricevere la concessione","Cominciare l’attività"],"ex":"Senza concessione accordata, nessuna attività.","ref":"Non nel materiale del corso · accesso ai mercati chiusi"},{"k":"tf","q":"Per una Sagl il capitale sociale minimo dev’essere interamente liberato alla fondazione.","v":true,"ex":"20 000 franchi interamente versati o coperti da conferimenti in natura.","ref":"Non nel materiale del corso · Codice delle obbligazioni, art. 621 e 773"},{"k":"case","s":"Un ristoratore vuole vendere alcol nel suo nuovo locale.","q":"Di che cosa ha bisogno in generale?","a":["Di un’autorizzazione o licenza del cantone","Di un monopolio della Confederazione","Di un capitale di 100 000 franchi","Dell’accordo dei ristoranti vicini"],"ex":"La vendita di alcol è soggetta ad autorizzazione cantonale: l’accesso è limitato.","ref":"Non nel materiale del corso · accesso ai mercati chiusi"},{"k":"case","s":"Un cliente le chiede perché solo la Posta può inoltrare la sua lettera di 20 grammi, mentre diverse aziende consegnano i suoi pacchi.","q":"Perché la Confederazione accorda questo monopolio alla Posta?","a":["Per finanziare il servizio universale in tutto il Paese","Per aumentare gli utili dei suoi concorrenti","Per vietare l’invio di pacchi da parte di privati","Per eliminare a poco a poco le bucalettere"],"ex":"Gli introiti del monopolio residuo contribuiscono al finanziamento del servizio universale.","ref":"Non nel materiale del corso · Posta CH, monopolio residuo"},{"k":"case","s":"Un’azienda privata di corrieri vuole consegnare buste di 200 g in Svizzera.","q":"Può farlo?","a":["Sì: sopra i 50 g il mercato è aperto","No: tutte le lettere sono riservate alla Posta","No: le serve un capitale di 1 milione","Sì, ma solo la domenica"],"ex":"Il monopolio copre solo le lettere fino a 50 g.","ref":"Non nel materiale del corso · Posta CH, monopolio residuo"},{"k":"case","s":"Un’azienda straniera vuole stabilirsi in Svizzera e vendere materiale medico.","q":"Perché questo mercato è più difficile da raggiungere di un mercato di t-shirt?","a":["Servono autorizzazioni per vendere prodotti medici","Gli svizzeri non comprano mai materiale medico all’estero","Le t-shirt sono un monopolio di Stato in tutti i cantoni","Il materiale medico è totalmente vietato in Svizzera"],"ex":"Regole giuridiche (autorizzazioni) limitano l’accesso ad alcuni mercati.","ref":"Non nel materiale del corso · accesso ai mercati chiusi"}]},{"code":"M204.7","t":"Il monopolio","g":"So analizzare le cause e le conseguenze di un monopolio su un mercato, spiegando come influenza i prezzi e le strategie delle aziende concorrenti.","col":"sky","ic":"crown","ch":[{"k":"qcm","q":"Che cos’è un monopolio?","a":["Un solo fornitore, senza concorrenza","Pochi grandi fornitori","Molti fornitori e clienti","Un solo cliente di fronte a diversi fornitori"],"ex":"Monopolio: un solo fornitore senza concorrenza.","ref":"Lezione 4.2.2"},{"k":"multi","q":"Quali possono essere le cause di un monopolio?","good":["Una legge che riserva il mercato","Una rete costosa impossibile da duplicare","Un brevetto che protegge un’invenzione"],"bad":["Una forte concorrenza","Migliaia di piccoli venditori"],"ex":"Monopolio legale, monopolio «naturale» (reti) o protezione di un’invenzione.","ref":"Non nel materiale del corso · effetti di un monopolio"},{"k":"qcm","q":"Qual è il rischio principale di un monopolio per i clienti?","a":["Prezzi più alti, per mancanza di concorrenza","Prezzi che calano sempre di più","Troppa scelta di prodotti per il cliente","Consegne fin troppo rapide"],"ex":"Senza concorrenti, il fornitore può fissare prezzi più alti.","ref":"Non nel materiale del corso · effetti di un monopolio"},{"k":"tf","q":"Un monopolio spinge fortemente l’azienda a innovare per tenersi i clienti.","v":false,"ex":"Senza concorrenza la pressione per innovare e abbassare i prezzi è debole.","ref":"Non nel materiale del corso · effetti di un monopolio"},{"k":"case","s":"Una sola azienda gestisce il gasdotto di una regione. Le economie domestiche non hanno un altro fornitore di gas.","q":"Qual è la causa di questo monopolio?","a":["Una rete costosa che sarebbe assurdo duplicare","Una cattiva qualità del servizio reso alle economie domestiche","Un gran numero di concorrenti nella regione","Un mercato settimanale di prodotti regionali"],"ex":"Per le reti (gas, acqua, ferrovia) una sola rete è più razionale: è un monopolio «naturale».","ref":"Lezione 4.2.2 · Non nel materiale del corso · effetti di un monopolio"},{"k":"case","s":"Un’azienda inventa un nuovo tipo di paletta e la protegge con un brevetto.","q":"Quale effetto ha il brevetto sul mercato di questa paletta?","a":["È l’unica a poterla fabbricare per un certo tempo","Tutti i concorrenti possono ormai copiarla liberamente","Il prezzo della paletta cala subito della metà","Il mercato di questa paletta diventa un polipolio"],"ex":"Il brevetto crea un monopolio temporaneo sull’invenzione.","ref":"Non nel materiale del corso · effetti di un monopolio"},{"k":"qcm","q":"Perché lo Stato sorveglia spesso i prezzi di un monopolio?","a":["Per evitare che i clienti paghino troppo","Per aumentare le imposte pagate dai clienti","Per obbligare il monopolio a chiudere in fretta","Per incoraggiare la pubblicità dell’azienda"],"ex":"In Svizzera, per esempio, un’autorità sorveglia la Posta e i suoi prezzi.","ref":"Non nel materiale del corso · effetti di un monopolio"},{"k":"case","s":"Il monopolio della Posta copre solo le lettere fino a 50 g. Per i pacchi, diverse aziende sono in concorrenza.","q":"Quale strategia adottano i concorrenti sui pacchi?","a":["Distinguersi per prezzo, termine o servizio","Lasciare tutti i pacchi alla Posta senza reagire","Aspettare pazientemente la fine del monopolio delle lettere","Copiare esattamente tutte le tariffe della Posta"],"ex":"Fuori dal monopolio, la concorrenza spinge a differenziarsi.","ref":"Non nel materiale del corso · Posta CH, monopolio residuo"},{"k":"sort","q":"Conseguenza di un monopolio o di una forte concorrenza?","c":["Monopolio","Forte concorrenza"],"it":[["Prezzi più alti",0],["Grande scelta per il cliente",1],["Poca innovazione",0],["Promozioni frequenti",1],["Cliente senza alternative",0],["Ricerca di nuovi servizi",1]],"ex":"La concorrenza giova al cliente; il monopolio lo rinchiude.","ref":"Non nel materiale del corso · effetti di un monopolio"},{"k":"match","q":"Abbini ogni causa a un esempio di monopolio.","p":[["Rete","Condotte d’acqua di una città"],["Legge","Lettere fino a 50 g"],["Brevetto","Un’invenzione protetta"]],"ex":"Sono tre cause frequenti di monopolio.","ref":"Lezione 4.2.2 · Non nel materiale del corso · effetti di un monopolio"},{"k":"odd","q":"Quale non è una conseguenza abituale di un monopolio?","a":["Un calo dei prezzi dovuto alla concorrenza","Prezzi più alti","Un cliente senza alternative","Poca pressione a innovare"],"ex":"In un monopolio non c’è appunto concorrenza.","ref":"Non nel materiale del corso · effetti di un monopolio"},{"k":"fill","q":"In un monopolio l’assenza di ___ permette al fornitore di fissare prezzi più alti.","a":["concorrenza","clienti","stock","trasporto"],"ex":"Senza concorrenti il cliente non ha alternative.","ref":"Non nel materiale del corso · effetti di un monopolio"},{"k":"case","s":"Un’azienda logistica dipende da un solo fornitore di pezzi di ricambio per i suoi carrelli, protetto da un brevetto.","q":"Quale rischio corre?","a":["Prezzi alti e nessun modo di negoziare","Troppe offerte concorrenti da confrontare","Un calo automatico dei prezzi","Nessun rischio: il brevetto protegge il cliente"],"ex":"Di fronte a un monopolio il cliente ha poco potere contrattuale.","ref":"Non nel materiale del corso · effetti di un monopolio"},{"k":"tf","q":"In un monopolio il cliente può cambiare facilmente fornitore.","v":false,"ex":"C’è un solo fornitore.","ref":"Lezione 4.2.2"},{"k":"qcm","q":"Quali esempi di monopolio cita il corso?","a":["Gasdotti, condotte d’acqua, rete di trasporto","Petrolio, elettricità, rete di telefonia mobile","Mercato settimanale e affitto di alloggi","Un datore di lavoro unico di fronte a diversi candidati"],"ex":"Gli altri esempi sono oligopoli, polipoli e un monopsonio.","ref":"Lezione 4.2.2"},{"k":"order","q":"Metta in ordine la sequenza che porta a prezzi alti in un monopolio.","a":["Un solo fornitore sul mercato","Nessun concorrente con cui confrontare","Il cliente non ha alternative","Il fornitore fissa un prezzo più alto"],"ex":"L’assenza di alternative dà al fornitore il potere di fissare il prezzo.","ref":"Non nel materiale del corso · effetti di un monopolio"},{"k":"case","s":"La scadenza di un brevetto permette ad altre aziende di fabbricare un medicamento.","q":"Che cosa succede in genere al prezzo?","a":["Cala grazie all’arrivo di concorrenti","Aumenta fortemente fin dall’anno seguente","Resta sempre esattamente lo stesso","Il medicamento scompare subito dal mercato"],"ex":"Con la concorrenza (generici) i prezzi calano.","ref":"Non nel materiale del corso · effetti di un monopolio"},{"k":"case","s":"Una città affida a una sola azienda la raccolta dei rifiuti per dieci anni.","q":"Come può la città evitare gli abusi di prezzo?","a":["Fissare i prezzi e la qualità nel contratto","Lasciare che l’azienda decida tutto da sola","Vietare la raccolta dei rifiuti","Ingaggiare cinque aziende per la stessa via"],"ex":"Un monopolio concesso si accompagna a regole e controlli.","ref":"Non nel materiale del corso · effetti di un monopolio"},{"k":"multi","q":"Quali strategie può adottare un’azienda concorrente di fronte a un monopolio?","good":["Puntare a un mercato vicino non riservato","Proporre un servizio diverso","Innovare con un prodotto sostitutivo"],"bad":["Copiare il prodotto brevettato","Ignorare completamente il mercato"],"ex":"I concorrenti aggirano il monopolio con mercati o prodotti vicini.","ref":"Non nel materiale del corso · effetti di un monopolio"},{"k":"case","s":"Le lettere di meno di 50 g sono riservate alla Posta. Un’azienda privata sviluppa un servizio di posta elettronica sicura per le fatture.","q":"Quale strategia usa?","a":["Proporre un prodotto sostitutivo","Entrare illegalmente nel monopolio","Comprare la Posta","Abbassare il prezzo dei francobolli"],"ex":"Un prodotto sostitutivo permette di fare concorrenza indiretta a un monopolio.","ref":"Non nel materiale del corso · Posta CH, monopolio residuo · Non nel materiale del corso · effetti di un monopolio"},{"k":"qcm","q":"Che cosa significa «monopolio naturale»?","a":["Una rete che è meglio costruire una sola volta","Un monopolio sulla vendita dei prodotti biologici","Un mercato in cui non si applica alcuna regola","Un mercato riservato ai soli agricoltori svizzeri"],"ex":"Duplicare una rete idrica o ferroviaria costerebbe troppo.","ref":"Non nel materiale del corso · effetti di un monopolio"},{"k":"tf","q":"Un monopolio può essere concesso dalla legge per garantire un servizio pubblico.","v":true,"ex":"Esempio: il monopolio delle lettere fino a 50 g finanzia il servizio universale della Posta.","ref":"Non nel materiale del corso · Posta CH, monopolio residuo"},{"k":"case","s":"In una piccola isola un solo negozio vende prodotti alimentari.","q":"Quale andamento dei prezzi ci si può aspettare?","a":["Prezzi più alti che sul continente","Prezzi più bassi che altrove","Promozioni esposte tutti i giorni","Prezzi fissati direttamente dai clienti"],"ex":"Unico fornitore, il negozio non deve allinearsi a dei concorrenti.","ref":"Non nel materiale del corso · effetti di un monopolio"},{"k":"qcm","q":"Come cambia un vecchio monopolio l’arrivo di un concorrente?","a":["Il cliente guadagna la scelta e i prezzi vengono messi sotto pressione","Per il cliente non cambia nulla, né il prezzo né la scelta","I prezzi aumentano ancora più di prima dell’apertura","Il mercato diventa allora un monopsonio di Stato"],"ex":"La concorrenza ridà potere al cliente.","ref":"Non nel materiale del corso · effetti di un monopolio"},{"k":"case","s":"Il suo deposito deve scegliere un fornitore di elettricità, ma il suo comune ne propone solo uno per i piccoli clienti.","q":"Che cosa può fare per ridurre la sua dipendenza?","a":["Produrre una parte della propria elettricità con pannelli solari","Cambiare fornitore di elettricità ogni settimana","Negoziare un prezzo dimezzato con il fornitore unico","Non usare più per niente l’elettricità al deposito"],"ex":"Di fronte a un fornitore unico, una soluzione sostitutiva riduce la dipendenza.","ref":"Non nel materiale del corso · effetti di un monopolio"}]}];
